      setResolvedRoot(dir);
      const spy = vi.spyOn(phaseNextCmd, 'runPhaseNext');
      spy.mockClear();
      try {
        const result = await client.callTool({
          name: 'phase_next',
          arguments: withProjectRoot({ change: changeName }),
