    });
  });

  describe('listTools — description', () => {
    afterEach(() => {
      setResolvedRoot(process.cwd());
      vi.mocked(archiDecide.createAdr).mockClear();
      vi.mocked(archiDecide.listAdrs).mockClear();
      vi.mocked(archiDecide.updateAdr).mockClear();
