    });

    it('archiDecideOutputSchema 各 action 分支 safeParse 通过', () => {
      expect(
        archiDecideOutputSchema.safeParse({ action: 'list', adrs: [], count: 0 }).success,
      ).toBe(true);
      expect(
        archiDecideOutputSchema.safeParse({
          action: 'create',
