        }).success,
      ).toBe(true);
      expect(
        archiDecideOutputSchema.safeParse({
          action: 'update',
          success: false,
          error: 'superseded_by required',
        }).success,
      ).toBe(true);
    });

    it('update 分支缺 file 时 inputSchema 拒参', () => {
      expect(
        archiDecideInputSchema.safeParse({
          project_root: mockResolve.root,
          action: 'update',
          status: 'accepted',
        }).success,
      ).toBe(false);
    });
